this.ambientTimer -= dt;
if (this.ambientTimer<=0) { this.ambientTimer=rand(0.12,0.3); const torches=ROOMS[roomId].torches; if(torches.length){ pick; pos=this.torchFlamePos(t); addParticle({kind:'spark',x:pos.x+rand(-4,4),y:pos.y, vx:rand(-4,4),vy:rand(-18,-30), gravity:-4, life:rand(.8,1.6), size:rand(1,2), color:'#ffb35a', alpha:.8})}}
