import {
  W, H, COLORS, clamp, rand, dist, circleRect, OPPOSITE, DOOR_CENTER,
} from './config.js';
import {
  ROOMS, MAP_CELLS, buildSolid, doorRect, roomSpawn, neighborId, tileCenter,
} from './world.js';
import { Player, Enemy, Boss, Projectile, Pickup } from './entities.js';
import { WorldView } from './view.js';
import {
  drawHUD, drawTitle, drawOverlays, makeVignette, buildTitleBackground, makeTitleEmbers,
} from './ui.js';

const DIRECTIONS = ['n', 's', 'w', 'e'];

export class Game {
  constructor(canvas, ctx, input, audio) {
    this.canvas = canvas;
    this.ctx = ctx;
    this.input = input;
    this.audio = audio;
    this.time = 0;
    this.mode = 'title';
    this.shake = 0;
    this.hitStop = 0;
    this.flashRed = 0;
    this.flashWhite = 0;
    this.bgCache = new Map();
    this.solidCache = new Map();
    this.titleTime = 0;
    this.titleEmbers = makeTitleEmbers();
    this.titleBg = buildTitleBackground();
    this.vignette = makeVignette();
    this.view = new WorldView();

    this.resetRunState();
    this.mode = 'title';
  }

  // -------------------------------------------------------------------------
  // Run setup
  // -------------------------------------------------------------------------
  resetRunState() {
    this.player = new Player(this, W / 2, H - 70, 'up');
    this.roomRuntimes = new Map();
    this.doorStates = {};
    for (const [id, room] of Object.entries(ROOMS)) {
      this.doorStates[id] = { ...room.doors };
    }
    this.roomId = '1,2';
    this.roomState = this.getRuntime('1,2');
    this.enemies = [];
    this.boss = null;
    this.projectiles = [];
    this.pickups = [];
    this.particles = [];
    this.visited = new Set(['1,2']);
    this.toast = null;
    this.message = null;
    this.reward = null;
    this.transition = null;
    this.roomBanner = null;
    this.bossBanner = 0;
    this.cinematic = 0;
    this.deathTimer = 0;
    this.victoryTime = 0;
    this.runTime = 0;
    this.kills = 0;
    this.deaths = 0;
    this.hintTimer = 7;
    this.doorHintCooldown = 0;
    this.ambientTimer = 0;
    this.shake = 0;
    this.hitStop = 0;
    this.flashRed = 0;
    this.flashWhite = 0;
    this.player.dead = false;
  }

  startRun() {
    this.resetRunState();
    this.mode = 'playing';
    this.enterRoom('1,2', null);
    this.player.x = W / 2;
    this.player.y = H - 70;
    this.player.facing = 'up';
    this.roomBanner = { name: ROOMS['1,2'].name, timer: 2.8, max: 2.8 };
    this.hintTimer = 9;
    this.audio.ensure();
    this.audio.startMusic('explore');
    this.showToast('Find the two small keys. The warden keeps the Boss Key.', 4.2);
  }

  debugStart(kind) {
    this.startRun();
    this.hintTimer = 0;
    const open = (id, dir) => {
      if (this.doorStates[id]) this.doorStates[id][dir] = 'open';
    };
    const clear = (...ids) => ids.forEach((id) => { this.getRuntime(id).cleared = true; });
    if (kind === 'boss') {
      clear('0,0', '0,1', '1,1', '2,1', '2,0');
      this.player.keys = 2;
      this.player.bossKey = true;
      ['0,0', '0,1', '1,1', '2,1', '2,0'].forEach((id) => this.visited.add(id));
      open('1,1', 'n');
      this.enterRoom('1,0', 's');
      this.player.x = W / 2;
      this.player.y = H - 66;
      this.player.facing = 'up';
      this.roomBanner = null;
      this.bossBanner = 0;
      this.cinematic = 0;
      if (this.boss) {
        this.boss.state = 'hover';
        this.boss.intro = false;
        this.boss.stateTimer = 0.7;
        this.boss.x = W / 2;
        this.boss.y = 92;
      }
      this.showToast('DEBUG: Boss arena', 1.5);
    } else if (kind === 'vault') {
      clear('0,1', '1,1', '2,1');
      this.player.keys = 2;
      ['0,1', '1,1', '2,1'].forEach((id) => this.visited.add(id));
      open('0,1', 'n');
      this.enterRoom('0,0', 's');
      this.player.x = W / 2;
      this.player.y = H - 66;
      this.player.facing = 'up';
      this.roomBanner = null;
      this.showToast('DEBUG: Warden arena', 1.5);
    } else if (kind === 'hub') {
      clear('0,1', '2,1');
      this.player.keys = 2;
      this.enterRoom('1,1', 's');
      this.player.x = W / 2;
      this.player.y = H - 70;
      this.roomBanner = null;
      this.showToast('DEBUG: Grand Hall', 1.5);
    } else if (kind === 'map') {
      this.player.keys = 2;
      this.player.bossKey = true;
      this.player.maxHp = 6;
      this.player.hp = 6;
      Object.keys(ROOMS).forEach((id) => this.visited.add(id));
      this.showToast('DEBUG: All doors visible', 1.5);
    }
  }

  getRuntime(id) {
    if (!this.roomRuntimes.has(id)) {
      const def = ROOMS[id];
      const pots = (def.props || [])
        .filter((p) => p.type === 'pot')
        .map((p) => ({ x: tileCenter(p.tx), y: tileCenter(p.ty), broken: false }));
      const chests = (def.chests || []).map((ch) => ({
        ...ch,
        x: tileCenter(ch.tx),
        y: tileCenter(ch.ty),
        opened: false,
        hidden: !!ch.hidden,
      }));
      this.roomRuntimes.set(id, { pots, chests, cleared: false });
    }
    return this.roomRuntimes.get(id);
  }

  getSolid(id) {
    if (!this.solidCache.has(id)) this.solidCache.set(id, buildSolid(ROOMS[id]));
    return this.solidCache.get(id);
  }

  enterRoom(id, fromDir) {
    const def = ROOMS[id];
    if (!def) return;
    this.roomId = id;
    this.visited.add(id);
    this.roomState = this.getRuntime(id);
    this.enemies = [];
    this.boss = null;
    this.projectiles = [];
    this.pickups = [];

    if (!this.roomState.cleared) {
      for (const e of def.enemies || []) {
        this.enemies.push(new Enemy(this, e.type, tileCenter(e.tx), tileCenter(e.ty)));
      }
    }

    const spawn = roomSpawn(id, fromDir);
    this.player.x = spawn.x;
    this.player.y = spawn.y;
    this.player.facing = spawn.facing;
    this.player.kbx = 0;
    this.player.kby = 0;

    if (def.boss && !this.roomState.cleared) {
      this.boss = new Boss(this, W / 2, 100);
      this.enemies.push(this.boss);
      this.bossBanner = 3.2;
      this.cinematic = 2.3;
      if (this.doorStates[id]) this.doorStates[id].s = 'sealed';
      if (this.doorStates['1,1']) this.doorStates['1,1'].n = 'sealed';
      this.audio.setMusic('boss');
    } else {
      this.audio.setMusic('explore');
    }

    this.roomBanner = { name: def.name, timer: 2.7, max: 2.7 };
  }

  // -------------------------------------------------------------------------
  // Update
  // -------------------------------------------------------------------------
  update(dt) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 28);
    this.flashRed = Math.max(0, this.flashRed - dt * 3.2);
    this.flashWhite = Math.max(0, this.flashWhite - dt * 1.7);

    if (this.input.justPressed('mute')) {
      const muted = this.audio.toggleMute();
      if (this.mode === 'playing' || this.mode === 'paused') {
        this.showToast(muted ? 'Sound off.' : 'Sound on.', 1.2);
      }
    }

    if (this.mode === 'title') {
      this.updateTitle(dt);
      return;
    }
    if (this.mode === 'playing') {
      if (this.input.justPressed('pause')) {
        this.togglePause();
        return;
      }
      this.updatePlaying(dt);
      return;
    }
    if (this.mode === 'paused') {
      if (this.input.justPressed('pause') || this.input.justPressed('confirm')) this.togglePause();
      return;
    }
    if (this.mode === 'reward') {
      this.updateReward(dt);
      return;
    }
    if (this.mode === 'message') {
      this.updateMessage(dt);
      return;
    }
    if (this.mode === 'dead') {
      this.updateDead(dt);
      return;
    }
    if (this.mode === 'victory') {
      this.updateVictory(dt);
    }
  }

  updateTitle(dt) {
    this.titleTime += dt;
    for (const e of this.titleEmbers) {
      e.y -= e.vy * dt;
      e.x += Math.sin(this.titleTime * 0.8 + e.phase) * 5 * dt;
      e.life -= dt;
      if (e.life <= 0) {
        e.x = rand(30, W - 30);
        e.y = rand(H * 0.5, H + 20);
        e.vy = rand(9, 26);
        e.life = rand(2.5, 7);
        e.size = rand(0.7, 2);
      }
    }
    if (
      this.input.justPressed('confirm') ||
      this.input.justPressed('attack') ||
      this.input.justPressed('interact')
    ) {
      this.startRun();
    }
  }

  updatePlaying(dt) {
    this.runTime += dt;
    this.updateTimers(dt);

    if (this.transition) {
      this.transition.t += dt;
      this.updateParticles(dt);
      if (this.transition.t >= this.transition.dur) this.transition = null;
      return;
    }

    if (this.cinematic > 0) {
      this.cinematic -= dt;
      this.updateAmbient(dt);
      this.updateParticles(dt);
      if (this.boss && !this.boss.dead) this.boss.update(dt);
      return;
    }

    if (this.hitStop > 0) {
      this.hitStop -= dt;
      return;
    }

    if (this.player.dead) return;

    this.player.update(dt);
    for (const e of this.enemies) {
      if (!e.dead) e.update(dt);
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
    if (this.mode !== 'playing') return;

    this.updateProjectiles(dt);
    if (this.mode !== 'playing') return;
    this.updatePickups(dt);
    this.updateParticles(dt);
    this.updateAmbient(dt);

    this.checkDoors();
    if (this.transition) return;
    this.checkRoomClear();
  }

  updateTimers(dt) {
    if (this.toast) {
      this.toast.timer -= dt;
      if (this.toast.timer <= 0) this.toast = null;
    }
    if (this.roomBanner) {
      this.roomBanner.timer -= dt;
      if (this.roomBanner.timer <= 0) this.roomBanner = null;
    }
    if (this.bossBanner > 0) this.bossBanner -= dt;
    if (this.hintTimer > 0) this.hintTimer -= dt;
    this.doorHintCooldown = Math.max(0, this.doorHintCooldown - dt);
  }

  updateProjectiles(dt) {
    for (const pr of this.projectiles) {
      if (!pr.dead) pr.update(dt);
      if (this.mode !== 'playing') return;
    }
    this.projectiles = this.projectiles.filter((p) => !p.dead);
  }

  updatePickups(dt) {
    for (const p of this.pickups) p.update(dt);
    this.pickups = this.pickups.filter((p) => !p.dead);
  }

  updateParticles(dt) {
    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += (p.gravity || 0) * dt;
      p.vx *= Math.pow(p.drag ?? 0.12, dt);
      p.vy *= Math.pow(p.drag ?? 0.12, dt);
      p.rot = (p.rot || 0) + (p.spin || 0) * dt;
    }
    this.particles = this.particles.filter((p) => p.life > 0);
  }

  updateAmbient(dt) {
    this.ambientTimer -= dt;
    if (this.ambientTimer > 0) return;
    this.ambientTimer = rand(0.1, 0.26);
    const room = ROOMS[this.roomId];
    if (!room || !room.torches || !room.torches.length) return;
    const t = room.torches[Math.floor(rand(0, room.torches.length))];
    const pos = this.torchFlamePos(t);
    this.addParticle({
      kind: 'spark',
      x: pos.x + rand(-4, 4),
      y: pos.y + rand(-2, 2),
      vx: rand(-5, 5),
      vy: rand(-30, -14),
      gravity: -3,
      drag: 0.7,
      life: rand(0.7, 1.6),
      maxLife: 1.6,
      size: rand(0.8, 1.8),
      color: Math.random() < 0.4 ? '#ffd27a' : '#ff9a4a',
      alpha: 0.85,
    });
  }

  torchFlamePos(t) {
    if (t.dir === 'n') return { x: t.tx * 16 + 8, y: 14 };
    if (t.dir === 's') return { x: t.tx * 16 + 8, y: H - 18 };
    if (t.dir === 'w') return { x: 19, y: t.ty * 16 + 8 };
    return { x: W - 19, y: t.ty * 16 + 8 };
  }

  togglePause() {
    if (this.mode === 'playing') {
      this.mode = 'paused';
      this.audio.sfx('pause');
    } else if (this.mode === 'paused') {
      this.mode = 'playing';
      this.audio.sfx('pause');
    }
  }

  // -------------------------------------------------------------------------
  // Doors, transitions, keys
  // -------------------------------------------------------------------------
  nearDoor(dir) {
    const p = this.player;
    if (dir === 'n') return Math.abs(p.x - W / 2) < 22 && p.y < 40;
    if (dir === 's') return Math.abs(p.x - W / 2) < 22 && p.y > H - 40;
    if (dir === 'w') return Math.abs(p.y - H / 2) < 24 && p.x < 40;
    return Math.abs(p.y - H / 2) < 24 && p.x > W - 40;
  }

  pastThreshold(dir) {
    const p = this.player;
    if (dir === 'n') return p.y < 10;
    if (dir === 's') return p.y > H - 10;
    if (dir === 'w') return p.x < 10;
    return p.x > W - 10;
  }

  checkDoors() {
    for (const dir of DIRECTIONS) {
      const state = this.doorStates[this.roomId]?.[dir];
      if (!state) continue;
      if (this.nearDoor(dir)) {
        if (state === 'locked') {
          if (this.doorHintCooldown > 0) return;
          if (this.player.keys > 0) {
            this.unlockDoor(dir, false);
          } else {
            this.showToast('Locked tight. A small key is needed.', 2.3);
            this.doorHintCooldown = 2.3;
          }
          return;
        }
        if (state === 'boss') {
          if (this.doorHintCooldown > 0) return;
          if (this.player.bossKey) {
            this.unlockDoor(dir, true);
          } else {
            this.showToast('The great door is bound to a Boss Key.', 2.7);
            this.doorHintCooldown = 2.7;
          }
          return;
        }
        if (state === 'sealed') {
          if (this.doorHintCooldown <= 0) {
            this.showToast(
              ROOMS[this.roomId].boss ? 'Sealed until the Hollow Eye falls.' : 'Sealed from the other side.',
              2.4
            );
            this.doorHintCooldown = 2.4;
          }
          return;
        }
      }
      if (state === 'open' && this.pastThreshold(dir)) {
        this.startTransition(dir);
        return;
      }
    }
  }

  unlockDoor(dir, isBoss) {
    const nd = neighborId(this.roomId, dir);
    if (isBoss) {
      this.player.bossKey = false;
      this.audio.sfx('bossDoor');
      this.shake = Math.max(this.shake, 9);
      this.flashWhite = 0.25;
      this.showToast('The Boss Key turns. The great door opens.', 3);
      this.cinematic = Math.max(this.cinematic, 0.55);
    } else {
      this.player.keys--;
      this.audio.sfx('unlock');
      this.showToast('The lock clicks open.', 1.8);
      this.shake = Math.max(this.shake, 2.5);
    }
    if (this.doorStates[this.roomId]) this.doorStates[this.roomId][dir] = 'open';
    if (nd && this.doorStates[nd]) this.doorStates[nd][OPPOSITE[dir]] = 'open';
    const c = DOOR_CENTER[dir];
    this.spark(c.x, c.y, 10, '#ffd27a');
    this.doorHintCooldown = 1.2;
  }

  startTransition(dir) {
    const target = neighborId(this.roomId, dir);
    if (!target || !ROOMS[target]) {
      this.showToast('A dead end.', 1.2);
      return;
    }
    const snap = document.createElement('canvas');
    snap.width = W;
    snap.height = H;
    const sctx = snap.getContext('2d');
    const oldShake = this.shake;
    this.shake = 0;
    this.view.drawScene(sctx, this, true);
    this.shake = oldShake;
    this.transition = { dir, t: 0, dur: 0.32, snap };
    this.enterRoom(target, dir);
  }

  // -------------------------------------------------------------------------
  // Interaction and items
  // -------------------------------------------------------------------------
  tryInteract(player) {
    const def = ROOMS[this.roomId];
    for (const sign of def.signs || []) {
      const x = tileCenter(sign.tx);
      const y = tileCenter(sign.ty);
      if (dist(player.x, player.y, x, y) < 31) {
        this.showMessage(sign.text);
        return;
      }
    }
    for (const chest of this.roomState.chests) {
      if (chest.hidden) continue;
      if (dist(player.x, player.y, chest.x, chest.y) < 31) {
        if (chest.opened) this.showToast('Empty.', 1.0);
        else this.openChest(chest);
        return;
      }
    }
  }

  openChest(chest) {
    if (chest.opened || chest.hidden) return;
    chest.opened = true;
    this.audio.sfx('chest');
    this.burst(chest.x, chest.y - 6, 14, '#ffd27a');
    let reward = null;
    if (chest.content === 'key') {
      this.player.keys++;
      reward = {
        kind: 'key',
        title: 'SMALL KEY',
        subtitle: this.player.keys > 1 ? 'Two locks now answer to you.' : 'One lock now answers to you.',
      };
    } else if (chest.content === 'bossKey') {
      this.player.bossKey = true;
      reward = {
        kind: 'bossKey',
        title: 'BOSS KEY',
        subtitle: 'The great door in the Grand Hall will yield.',
      };
      this.shake = Math.max(this.shake, 6);
    } else if (chest.content === 'heartContainer') {
      this.player.maxHp++;
      this.player.hp = this.player.maxHp;
      reward = {
        kind: 'heartContainer',
        title: 'HEART CONTAINER',
        subtitle: 'Your life force grows.',
      };
      this.audio.sfx('heart');
    }
    if (reward) {
      this.reward = { ...reward, timer: 2.8 };
      this.mode = 'reward';
      this.flashWhite = 0.22;
    }
  }

  revealChest(id) {
    for (const runtime of this.roomRuntimes.values()) {
      for (const chest of runtime.chests) {
        if (chest.id === id && chest.hidden) {
          chest.hidden = false;
          if (this.roomState === runtime) {
            this.burst(chest.x, chest.y, 22, '#ffd27a');
            this.spark(chest.x, chest.y, 14, '#fff3c4');
          }
          this.showToast('The Warden falls. A Boss Key chest appears.', 3.2);
          this.audio.sfx('secret');
          this.shake = Math.max(this.shake, 5);
        }
      }
    }
  }

  showMessage(lines) {
    this.message = { lines, shown: 0 };
    this.mode = 'message';
    this.audio.sfx('pickup');
  }

  updateMessage(dt) {
    const total = this.message.lines.join('').length;
    this.message.shown += dt * 52;
    const advance =
      this.input.justPressed('interact') ||
      this.input.justPressed('confirm') ||
      this.input.justPressed('attack');
    if (advance) {
      if (this.message.shown < total) {
        this.message.shown = total;
      } else {
        this.message = null;
        this.mode = 'playing';
      }
    }
  }

  updateReward(dt) {
    this.reward.timer -= dt;
    this.updateParticles(dt);
    const advance =
      this.input.justPressed('attack') ||
      this.input.justPressed('confirm') ||
      this.input.justPressed('interact');
    if ((advance && this.reward.timer < 2.1) || this.reward.timer <= 0) {
      this.reward = null;
      this.mode = 'playing';
      this.player.attackCooldown = 0.12;
    }
  }

  // -------------------------------------------------------------------------
  // Death and victory
  // -------------------------------------------------------------------------
  onPlayerDeath() {
    this.deaths++;
    this.mode = 'dead';
    this.deathTimer = 0;
    this.player.dead = true;
    this.player.kbx = 0;
    this.player.kby = 0;
    this.audio.sfx('death');
    this.audio.setMusic(null);
    this.shake = Math.max(this.shake, 9);
    this.flashRed = 0.5;
  }

  updateDead(dt) {
    this.deathTimer += dt;
    this.updateParticles(dt);
    if (this.deathTimer > 0.9 && (this.input.justPressed('confirm') || this.input.justPressed('attack'))) {
      this.respawn();
    }
  }

  respawn() {
    this.player.dead = false;
    this.player.hp = this.player.maxHp;
    this.player.invuln = 1.4;
    this.player.kbx = 0;
    this.player.kby = 0;
    this.player.attackTimer = 0;
    this.player.attackCooldown = 0;
    this.transition = null;
    this.reward = null;
    this.message = null;
    this.cinematic = 0;
    this.bossBanner = 0;
    this.boss = null;
    if (!this.getRuntime('1,0').cleared) {
      if (this.doorStates['1,1']) this.doorStates['1,1'].n = 'open';
      if (this.doorStates['1,0']) this.doorStates['1,0'].s = 'open';
    }
    this.enterRoom('1,2', null);
    this.player.x = W / 2;
    this.player.y = H - 70;
    this.player.facing = 'up';
    this.mode = 'playing';
    this.roomBanner = { name: 'Sealed Entrance', timer: 2.2, max: 2.2 };
    this.audio.startMusic('explore');
    this.showToast('You rise again. Your keys remain.', 3.2);
  }

  onBossDefeated() {
    this.getRuntime('1,0').cleared = true;
    if (this.doorStates['1,0']) this.doorStates['1,0'].s = 'open';
    if (this.doorStates['1,1']) this.doorStates['1,1'].n = 'open';
    this.mode = 'victory';
    this.victoryTime = 0;
    this.flashWhite = 1;
    this.audio.setMusic(null);
    this.audio.sfx('victory');
    this.burst(this.player.x, this.player.y - 10, 40, '#ffd27a');
  }

  updateVictory(dt) {
    this.victoryTime += dt;
    this.updateParticles(dt);
    if (this.victoryTime > 1.4 && (this.input.justPressed('confirm') || this.input.justPressed('attack'))) {
      this.startRun();
    }
  }

  // -------------------------------------------------------------------------
  // Collision & movement
  // -------------------------------------------------------------------------
  circleCollides(x, y, r) {
    if (x - r < 0 || x + r > W || y - r < 0 || y + r > H) return true;
    const solid = this.getSolid(this.roomId);
    const tx0 = Math.max(0, Math.floor((x - r) / 16));
    const tx1 = Math.min(31, Math.floor((x + r) / 16));
    const ty0 = Math.max(0, Math.floor((y - r) / 16));
    const ty1 = Math.min(17, Math.floor((y + r) / 16));
    for (let ty = ty0; ty <= ty1; ty++) {
      for (let tx = tx0; tx <= tx1; tx++) {
        if (solid[ty]?.[tx] && circleRect(x, y, r, tx * 16, ty * 16, 16, 16)) return true;
      }
    }
    for (const pot of this.roomState.pots) {
      if (!pot.broken && circleRect(x, y, r, pot.x - 6, pot.y - 6, 12, 12)) return true;
    }
    for (const chest of this.roomState.chests) {
      if (!chest.hidden && circleRect(x, y, r, chest.x - 9, chest.y - 7, 18, 16)) return true;
    }
    for (const dir of DIRECTIONS) {
      const state = this.doorStates[this.roomId]?.[dir];
      const dr = doorRect(dir, state);
      if (dr && circleRect(x, y, r, dr.x, dr.y, dr.w, dr.h)) return true;
    }
    return false;
  }

  moveBody(body, dx, dy) {
    let blocked = false;
    if (dx !== 0) {
      body.x += dx;
      if (this.circleCollides(body.x, body.y, body.r)) {
        body.x -= dx;
        blocked = true;
      }
    }
    if (dy !== 0) {
      body.y += dy;
      if (this.circleCollides(body.x, body.y, body.r)) {
        body.y -= dy;
        blocked = true;
      }
    }
    return blocked;
  }

  canControl() {
    return this.mode === 'playing' && !this.transition && this.cinematic <= 0 && !this.player.dead;
  }

  // -------------------------------------------------------------------------
  // Combat helpers, particles, pickups
  // -------------------------------------------------------------------------
  spawnArrow(x, y, angle) {
    const speed = 148;
    this.projectiles.push(
      new Projectile(this, x, y, Math.cos(angle) * speed, Math.sin(angle) * speed, 'arrow', 1, 'enemy')
    );
  }

  spawnPickup(x, y, kind) {
    this.pickups.push(new Pickup(this, x, y, kind));
  }

  onEnemyDeath(enemy) {
    this.kills++;
    if (this.mode !== 'playing') return;
    const def = ROOMS[this.roomId];
    if (def.boss) return;
    if ((def.enemies || []).length === 0) return;
    if (this.enemies.every((e) => e.dead)) {
      this.roomState.cleared = true;
      if (this.roomId !== '0,0') this.showToast('The room falls silent.', 1.6);
    }
  }

  checkRoomClear() {
    const def = ROOMS[this.roomId];
    if (def.boss || this.roomState.cleared) return;
    if (!(def.enemies || []).length) return;
    if (this.enemies.every((e) => e.dead)) {
      this.roomState.cleared = true;
      if (this.roomId !== '0,0') this.showToast('The room falls silent.', 1.6);
    }
  }

  breakPot(pot) {
    if (pot.broken) return;
    pot.broken = true;
    this.audio.sfx('hit');
    this.burst(pot.x, pot.y, 10, '#8fb0c4');
    this.shake = Math.max(this.shake, 1.2);
    if (Math.random() < 0.32) this.spawnPickup(pot.x, pot.y - 4, 'heart');
  }

  addParticle(p) {
    this.particles.push({
      life: 1,
      maxLife: 1,
      vx: 0,
      vy: 0,
      size: 2,
      color: '#fff',
      kind: 'spark',
      gravity: 0,
      drag: 0.15,
      alpha: 1,
      ...p,
    });
  }

  spark(x, y, n, color) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(30, 130);
      this.addParticle({
        kind: 'spark',
        x,
        y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        gravity: 80,
        drag: 0.05,
        life: rand(0.2, 0.55),
        maxLife: 0.55,
        size: rand(1, 2.4),
        color,
      });
    }
  }

  dust(x, y, n) {
    for (let i = 0; i < n; i++) {
      this.addParticle({
        kind: 'dust',
        x: x + rand(-6, 6),
        y: y + rand(-2, 2),
        vx: rand(-24, 24),
        vy: rand(-28, -6),
        gravity: -8,
        drag: 0.4,
        life: rand(0.3, 0.75),
        maxLife: 0.75,
        size: rand(1.5, 3.4),
        color: '#6b6278',
        alpha: 0.5,
      });
    }
  }

  burst(x, y, n, color) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(30, 170);
      this.addParticle({
        kind: Math.random() < 0.6 ? 'spark' : 'shard',
        x,
        y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s - 30,
        gravity: 150,
        drag: 0.08,
        life: rand(0.35, 0.9),
        maxLife: 0.9,
        size: rand(1.2, 3.4),
        color,
        rot: rand(0, 6),
        spin: rand(-8, 8),
      });
    }
    this.addParticle({
      kind: 'ring',
      x,
      y,
      life: 0.35,
      maxLife: 0.35,
      size: 8,
      color,
    });
  }

  showToast(text, duration = 2) {
    this.toast = { text, timer: duration, max: duration };
  }

  // -------------------------------------------------------------------------
  // Render entry point
  // -------------------------------------------------------------------------
  render() {
    const ctx = this.ctx;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, W, H);

    if (this.mode === 'title') {
      drawTitle(ctx, this);
      return;
    }

    this.view.drawScene(ctx, this, false);

    if (this.transition) {
      const tr = this.transition;
      const p = clamp(tr.t / tr.dur, 0, 1);
      const ease = 1 - Math.pow(1 - p, 2);
      let ox = 0;
      let oy = 0;
      if (tr.dir === 'n') oy = ease * H;
      else if (tr.dir === 's') oy = -ease * H;
      else if (tr.dir === 'e') ox = -ease * W;
      else if (tr.dir === 'w') ox = ease * W;
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, W, H);
      ctx.clip();
      ctx.drawImage(tr.snap, ox, oy);
      ctx.restore();
    }

    drawHUD(ctx, this);
    drawOverlays(ctx, this);
  }
}

import { W, H, TILE, COLORS, hash, rand, clamp } from './config.js';
import { ROOMS } from './world.js';
import {
  drawChest, drawPot, drawSign, drawFlame, drawTorchBracket, drawPickup,
  drawProjectile, drawParticle, rect, shadow,
} from './sprites.js';

const c = (n) => n * TILE + TILE / 2;

export class WorldView {
  constructor() {
    this.bgCache = new Map();
  }

  // -------------------------------------------------------------------------
  // Room background cache
  // -------------------------------------------------------------------------
  getBackground(roomId) {
    if (this.bgCache.has(roomId)) return this.bgCache.get(roomId);
    const room = ROOMS[roomId];
    const cv = document.createElement('canvas');
    cv.width = W;
    cv.height = H;
    const g = cv.getContext('2d');
    g.fillStyle = '#0a0810';
    g.fillRect(0, 0, W, H);

    // floor
    for (let y = 1; y <= 16; y++) {
      for (let x = 1; x <= 30; x++) this.drawFloorTile(g, x * TILE, y * TILE, x, y);
    }

    // thresholds beneath every door
    if (room.doors.n) {
      this.drawFloorTile(g, 15 * TILE, 0, 15, 0);
      this.drawFloorTile(g, 16 * TILE, 0, 16, 0);
    }
    if (room.doors.s) {
      this.drawFloorTile(g, 15 * TILE, 17 * TILE, 15, 17);
      this.drawFloorTile(g, 16 * TILE, 17 * TILE, 16, 17);
    }
    if (room.doors.w) {
      this.drawFloorTile(g, 0, 8 * TILE, 0, 8);
      this.drawFloorTile(g, 0, 9 * TILE, 0, 9);
    }
    if (room.doors.e) {
      this.drawFloorTile(g, 31 * TILE, 8 * TILE, 31, 8);
      this.drawFloorTile(g, 31 * TILE, 9 * TILE, 31, 9);
    }

    if (room.carpet) this.drawCarpet(g, room.carpet);
    if (room.mosaic) this.drawMosaic(g, room.mosaic, room.boss);

    // walls
    const doorTiles = new Set();
    for (const dir of Object.keys(room.doors)) {
      if (dir === 'n') { doorTiles.add('15,0'); doorTiles.add('16,0'); }
      if (dir === 's') { doorTiles.add('15,17'); doorTiles.add('16,17'); }
      if (dir === 'w') { doorTiles.add('0,8'); doorTiles.add('0,9'); }
      if (dir === 'e') { doorTiles.add('31,8'); doorTiles.add('31,9'); }
    }
    for (let x = 0; x < 32; x++) {
      for (const y of [0, 17]) {
        if (!doorTiles.has(`${x},${y}`)) this.drawWallTile(g, x * TILE, y * TILE, x, y, y === 0 ? 'n' : 's');
      }
    }
    for (let y = 1; y < 17; y++) {
      if (!doorTiles.has(`0,${y}`)) this.drawWallTile(g, 0, y * TILE, 0, y, 'w');
      if (!doorTiles.has(`31,${y}`)) this.drawWallTile(g, 31 * TILE, y * TILE, 31, y, 'e');
    }

    // inner shadow around the room
    let grad = g.createLinearGradient(0, TILE, 0, TILE + 34);
    grad.addColorStop(0, 'rgba(3,2,7,0.62)');
    grad.addColorStop(1, 'rgba(3,2,7,0)');
    g.fillStyle = grad;
    g.fillRect(TILE, TILE, W - TILE * 2, 34);
    grad = g.createLinearGradient(0, H - TILE, 0, H - TILE - 30);
    grad.addColorStop(0, 'rgba(3,2,7,0.55)');
    grad.addColorStop(1, 'rgba(3,2,7,0)');
    g.fillStyle = grad;
    g.fillRect(TILE, H - TILE - 30, W - TILE * 2, 30);
    grad = g.createLinearGradient(TILE, 0, TILE + 30, 0);
    grad.addColorStop(0, 'rgba(3,2,7,0.5)');
    grad.addColorStop(1, 'rgba(3,2,7,0)');
    g.fillStyle = grad;
    g.fillRect(TILE, TILE, 30, H - TILE * 2);
    grad = g.createLinearGradient(W - TILE, 0, W - TILE - 30, 0);
    grad.addColorStop(0, 'rgba(3,2,7,0.5)');
    grad.addColorStop(1, 'rgba(3,2,7,0)');
    g.fillStyle = grad;
    g.fillRect(W - TILE - 30, TILE, 30, H - TILE * 2);

    for (const b of room.banners || []) this.drawBanner(g, b);
    for (const p of room.props || []) {
      if (p.type === 'pillar') this.drawPillar(g, p);
      else if (p.type === 'statue') this.drawStatue(g, p);
      else if (p.type === 'rubble') this.drawRubble(g, p);
      else if (p.type === 'bones') this.drawBones(g, p);
    }

    for (const t of room.torches || []) this.drawTorchBracketFor(g, t);

    // faint wall grime
    g.globalAlpha = 0.1;
    g.fillStyle = '#000';
    for (let i = 0; i < 20; i++) {
      const x = hash(i, 3) * W;
      const y = hash(i, 7) * H;
      g.fillRect(x, y, 1, 1);
    }
    g.globalAlpha = 1;

    this.bgCache.set(roomId, cv);
    return cv;
  }

  drawFloorTile(g, px, py, x, y) {
    const n = hash(x, y);
    const base = n > 0.66 ? '#201e2f' : n > 0.3 ? '#1c1a29' : '#191725';
    g.fillStyle = base;
    g.fillRect(px, py, TILE, TILE);
    // bevel
    g.fillStyle = 'rgba(255,255,255,0.035)';
    g.fillRect(px, py, TILE, 1);
    g.fillRect(px, py, 1, TILE);
    g.fillStyle = 'rgba(0,0,0,0.24)';
    g.fillRect(px, py + TILE - 1, TILE, 1);
    g.fillRect(px + TILE - 1, py, 1, TILE);
    // seams
    g.fillStyle = 'rgba(6,5,10,0.45)';
    g.fillRect(px, py + 8, TILE, 1);
    g.fillRect(px + 8, py, 1, TILE);
    if (n > 0.88) {
      g.strokeStyle = 'rgba(0,0,0,0.4)';
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(px + 4, py + 3);
      g.lineTo(px + 8, py + 7);
      g.lineTo(px + 6, py + 12);
      g.stroke();
    }
    if (n < 0.075) {
      g.fillStyle = 'rgba(70,105,66,0.3)';
      g.beginPath();
      g.arc(px + 5, py + 11, 2.5, 0, Math.PI * 2);
      g.arc(px + 9, py + 9, 1.8, 0, Math.PI * 2);
      g.fill();
    }
  }

  drawWallTile(g, px, py, x, y, side) {
    const n = hash(x * 2 + 11, y * 3 + 7);
    g.fillStyle = '#2b2840';
    g.fillRect(px, py, TILE, TILE);
    g.fillStyle = n > 0.5 ? '#322e4a' : '#2e2a45';
    g.fillRect(px + 1, py + 2, TILE - 2, TILE - 4);
    // top face
    g.fillStyle = '#484463';
    g.fillRect(px, py, TILE, 2);
    g.fillStyle = '#3c3856';
    g.fillRect(px, py + 2, TILE, 2);
    // bottom shadow
    g.fillStyle = '#171522';
    g.fillRect(px, py + TILE - 3, TILE, 3);
    // brick seams
    g.fillStyle = 'rgba(8,7,14,0.55)';
    g.fillRect(px, py + 8, TILE, 1);
    const seamX = y % 2 === 0 ? px + 5 : px + 11;
    g.fillRect(seamX, py + 2, 1, 6);
    g.fillRect(y % 2 === 0 ? px + 12 : px + 3, py + 9, 1, 5);
    // highlights
    g.fillStyle = 'rgba(255,255,255,0.05)';
    g.fillRect(px + 1, py + 3, TILE - 2, 1);
    if (n > 0.82) {
      g.strokeStyle = 'rgba(10,8,16,0.65)';
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(px + 3, py + 4);
      g.lineTo(px + 6, py + 7);
      g.lineTo(px + 5, py + 12);
      g.stroke();
    }
    if (n < 0.13) {
      g.fillStyle = 'rgba(72,104,66,0.4)';
      g.fillRect(px + 2, py + 11, 3, 2);
      g.fillRect(px + 4, py + 9, 2, 3);
    }
    if (side === 'n' && y === 0) {
      g.fillStyle = 'rgba(4,3,8,0.9)';
      g.fillRect(px, py, TILE, 1);
    }
  }

  drawCarpet(g, kind) {
    const left = 14 * TILE;
    const right = 18 * TILE;
    const drawStrip = (x, y, w, h) => {
      g.fillStyle = '#5b1d29';
      g.fillRect(x, y, w, h);
      g.fillStyle = '#6d2431';
      g.fillRect(x + 3, y + 3, w - 6, h - 6);
      g.strokeStyle = 'rgba(200,164,74,0.55)';
      g.lineWidth = 2;
      g.strokeRect(x + 1, y + 1, w - 2, h - 2);
      g.strokeStyle = 'rgba(30,10,14,0.6)';
      g.lineWidth = 1;
      g.strokeRect(x + 5, y + 5, w - 10, h - 10);
      // diamond pattern
      g.fillStyle = 'rgba(216,180,90,0.12)';
      for (let yy = y + 12; yy < y + h - 8; yy += 22) {
        for (let xx = x + 12; xx < x + w - 8; xx += 22) {
          g.beginPath();
          g.moveTo(xx, yy - 4);
          g.lineTo(xx + 4, yy);
          g.lineTo(xx, yy + 4);
          g.lineTo(xx - 4, yy);
          g.closePath();
          g.fill();
        }
      }
    };
    if (kind === 'vertical') drawStrip(left, TILE, right - left, H - TILE * 2);
    if (kind === 'cross') {
      drawStrip(left, TILE, right - left, H - TILE * 2);
      drawStrip(TILE, 7 * TILE, W - TILE * 2, 4 * TILE);
    }
  }

  drawMosaic(g, mosaic, boss) {
    const x = c(mosaic.tx);
    const y = c(mosaic.ty);
    const r = mosaic.r;
    g.save();
    g.translate(x, y);
    g.globalAlpha = 0.62;
    g.strokeStyle = boss ? 'rgba(190,72,86,0.55)' : 'rgba(94,178,170,0.4)';
    g.lineWidth = 2;
    g.beginPath();
    g.arc(0, 0, r, 0, Math.PI * 2);
    g.stroke();
    g.lineWidth = 1;
    g.strokeStyle = 'rgba(216,180,90,0.34)';
    g.beginPath();
    g.arc(0, 0, r - 7, 0, Math.PI * 2);
    g.stroke();
    g.beginPath();
    g.arc(0, 0, r - 18, 0, Math.PI * 2);
    g.stroke();
    // rune marks
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      g.save();
      g.rotate(a);
      g.fillStyle = boss ? 'rgba(200,78,88,0.4)' : 'rgba(216,180,90,0.32)';
      g.beginPath();
      g.moveTo(r - 14, -3);
      g.lineTo(r - 8, 0);
      g.lineTo(r - 14, 3);
      g.closePath();
      g.fill();
      g.restore();
    }
    // central motif
    g.strokeStyle = boss ? 'rgba(210,88,92,0.62)' : 'rgba(79,185,176,0.5)';
    g.lineWidth = 2;
    if (boss) {
      g.beginPath();
      g.ellipse(0, 0, 20, 11, 0, 0, Math.PI * 2);
      g.stroke();
      g.fillStyle = 'rgba(210,88,92,0.55)';
      g.beginPath();
      g.ellipse(0, 0, 7, 9, 0, 0, Math.PI * 2);
      g.fill();
      g.fillStyle = 'rgba(10,6,12,0.9)';
      g.fillRect(-1.5, -8, 3, 16);
    } else {
      for (let i = 0; i < 3; i++) {
        const a = -Math.PI / 2 + (i / 3) * Math.PI * 2;
        g.beginPath();
        g.moveTo(Math.cos(a) * 17, Math.sin(a) * 17);
        g.lineTo(Math.cos(a + 2.2) * 17, Math.sin(a + 2.2) * 17);
        g.lineTo(Math.cos(a + 1.1) * 8, Math.sin(a + 1.1) * 8);
        g.closePath();
        g.stroke();
      }
    }
    g.restore();
    g.globalAlpha = 1;
  }

  drawBanner(g, b) {
    const x = b.tx * TILE + 8;
    const top = 3;
    g.fillStyle = 'rgba(4,3,8,0.5)';
    g.fillRect(x - 9, top + 3, 18, 2);
    rect(g, x - 9, top, 18, 2, '#3a2a1a');
    rect(g, x - 9, top, 2, 2, COLORS.gold);
    rect(g, x + 7, top, 2, 2, COLORS.gold);
    g.fillStyle = '#17121f';
    g.beginPath();
    g.moveTo(x - 8, top + 2);
    g.lineTo(x + 8, top + 2);
    g.lineTo(x + 8, top + 25);
    g.lineTo(x, top + 21);
    g.lineTo(x - 8, top + 25);
    g.closePath();
    g.fill();
    g.fillStyle = '#6c1f2c';
    g.beginPath();
    g.moveTo(x - 6, top + 3);
    g.lineTo(x + 6, top + 3);
    g.lineTo(x + 6, top + 23);
    g.lineTo(x, top + 19);
    g.lineTo(x - 6, top + 23);
    g.closePath();
    g.fill();
    g.fillStyle = 'rgba(255,255,255,0.08)';
    g.fillRect(x - 5, top + 4, 2, 17);
    g.strokeStyle = 'rgba(216,180,90,0.6)';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(x - 6, top + 3);
    g.lineTo(x + 6, top + 3);
    g.stroke();
    g.fillStyle = COLORS.gold;
    g.beginPath();
    g.moveTo(x, top + 8);
    g.lineTo(x + 4, top + 13);
    g.lineTo(x, top + 18);
    g.lineTo(x - 4, top + 13);
    g.closePath();
    g.fill();
    g.fillStyle = '#5b1d29';
    g.beginPath();
    g.moveTo(x, top + 10);
    g.lineTo(x + 2, top + 13);
    g.lineTo(x, top + 16);
    g.lineTo(x - 2, top + 13);
    g.closePath();
    g.fill();
  }

  drawPillar(g, p) {
    const x = p.tx * TILE;
    const y = p.ty * TILE;
    shadow(g, x + 16, y + 32, 17, 5, 0.45);
    // base
    rect(g, x + 1, y + 22, 30, 9, '#171522');
    rect(g, x + 2, y + 21, 28, 7, '#3b3652');
    rect(g, x + 2, y + 21, 28, 2, '#555070');
    rect(g, x + 4, y + 27, 24, 2, '#252236');
    // column
    rect(g, x + 5, y - 10, 22, 33, '#171522');
    rect(g, x + 6, y - 9, 20, 31, '#3f3a59');
    rect(g, x + 7, y - 8, 7, 29, '#4b4668');
    rect(g, x + 17, y - 6, 8, 26, '#332f4b');
    // bands
    rect(g, x + 6, y + 2, 20, 2, '#2a2640');
    rect(g, x + 6, y + 14, 20, 2, '#2a2640');
    // capital
    rect(g, x + 1, y - 16, 30, 8, '#171522');
    rect(g, x + 2, y - 15, 28, 6, '#4a4566');
    rect(g, x + 2, y - 15, 28, 2, '#5e587d');
    // highlight
    rect(g, x + 7, y - 6, 2, 24, 'rgba(255,255,255,0.06)');
    if (hash(p.tx, p.ty) > 0.5) {
      g.strokeStyle = 'rgba(10,8,16,0.5)';
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(x + 15, y - 2);
      g.lineTo(x + 18, y + 4);
      g.lineTo(x + 16, y + 8);
      g.stroke();
    }
  }

  drawStatue(g, p) {
    const x = p.tx * TILE + 16;
    const y = p.ty * TILE + 16;
    shadow(g, x, y + 18, 16, 5, 0.42);
    rect(g, x - 14, y + 10, 28, 9, '#171522');
    rect(g, x - 13, y + 9, 26, 7, '#3a3650');
    rect(g, x - 13, y + 9, 26, 2, '#4d4868');
    // figure
    rect(g, x - 8, y - 8, 16, 18, '#171522');
    rect(g, x - 7, y - 7, 14, 16, '#4a5a5e');
    rect(g, x - 6, y - 6, 12, 4, '#5d7376');
    rect(g, x - 5, y - 15, 10, 9, '#171522');
    rect(g, x - 4, y - 14, 8, 7, '#5d7376');
    rect(g, x - 3, y - 12, 6, 2, '#1b2a2a');
    // sword
    rect(g, x + 7, y - 12, 2, 22, '#171522');
    rect(g, x + 7, y - 11, 1, 18, '#8b9a9e');
    rect(g, x + 5, y + 5, 6, 1, COLORS.goldDark);
    // shield
    rect(g, x - 12, y - 5, 6, 10, '#171522');
    rect(g, x - 11, y - 4, 4, 8, '#5b4a32');
    rect(g, x - 10, y - 2, 2, 3, COLORS.goldDark);
    // moss
    g.fillStyle = 'rgba(80,120,90,0.25)';
    g.fillRect(x - 6, y + 2, 4, 2);
    g.fillRect(x + 2, y - 14, 3, 2);
  }

  drawRubble(g, p) {
    const x = p.tx * TILE + 8;
    const y = p.ty * TILE + 8;
    const n = hash(p.tx, p.ty);
    for (let i = 0; i < 4; i++) {
      const ox = (hash(p.tx + i, p.ty) - 0.5) * 16;
      const oy = (hash(p.tx, p.ty + i) - 0.5) * 12;
      const s = 2 + hash(i, p.tx) * 3;
      rect(g, x + ox - s / 2, y + oy - s / 2, s, s * 0.8, i % 2 ? '#3a3550' : '#2b2740');
      rect(g, x + ox - s / 2, y + oy - s / 2, s, 1, 'rgba(255,255,255,0.07)');
    }
    if (n > 0.6) {
      g.fillStyle = 'rgba(74,106,70,0.25)';
      g.fillRect(x - 2, y + 3, 4, 2);
    }
  }

  drawBones(g, p) {
    const x = p.tx * TILE + 8;
    const y = p.ty * TILE + 8;
    g.save();
    g.translate(x, y);
    g.fillStyle = '#bdb6a4';
    g.strokeStyle = '#17121f';
    g.lineWidth = 1;
    // skull
    g.beginPath();
    g.ellipse(-2, -1, 4.5, 4, 0, 0, Math.PI * 2);
    g.fill();
    g.stroke();
    g.fillStyle = '#17121f';
    g.fillRect(-4, -2, 1.5, 2);
    g.fillRect(-0.5, -2, 1.5, 2);
    // bones
    g.strokeStyle = '#bdb6a4';
    g.lineWidth = 1.6;
    g.beginPath();
    g.moveTo(4, 3);
    g.lineTo(10, -3);
    g.moveTo(5, 6);
    g.lineTo(9, 8);
    g.stroke();
    g.fillStyle = '#bdb6a4';
    g.fillRect(9, -4, 2, 2);
    g.fillRect(9, 7, 2, 2);
    g.restore();
  }

  drawTorchBracketFor(g, t) {
    const pos = { n: [t.tx * TILE + 8, 10], s: [t.tx * TILE + 8, H - 11], w: [14, t.ty * TILE + 8], e: [W - 14, t.ty * TILE + 8] }[t.dir];
    // scorch mark
    const grd = g.createRadialGradient(pos[0], pos[1], 0, pos[0], pos[1], 18);
    grd.addColorStop(0, 'rgba(0,0,0,0.45)');
    grd.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = grd;
    g.fillRect(pos[0] - 18, pos[1] - 18, 36, 36);
    drawTorchBracket(g, pos[0], pos[1], t.dir);
  }

  // -------------------------------------------------------------------------
  // Doors
  // -------------------------------------------------------------------------
  drawDoor(ctx, dir, state, game) {
    ctx.save();
    if (dir === 'n') ctx.translate(240, 0);
    else if (dir === 's') { ctx.translate(272, H); ctx.rotate(Math.PI); }
    else if (dir === 'w') { ctx.translate(0, 160); ctx.rotate(-Math.PI / 2); }
    else { ctx.translate(W, 128); ctx.rotate(Math.PI / 2); }

    // stone jambs
    ctx.fillStyle = '#171522';
    ctx.fillRect(-6, 0, 6, 24);
    ctx.fillRect(32, 0, 6, 24);
    ctx.fillStyle = '#3b3652';
    ctx.fillRect(-5, 0, 4, 22);
    ctx.fillRect(32, 0, 4, 22);
    ctx.fillStyle = '#4c4768';
    ctx.fillRect(-5, 0, 1, 22);
    ctx.fillRect(32, 0, 1, 22);
    ctx.fillStyle = '#211e30';
    ctx.fillRect(-6, 20, 44, 4);
    ctx.fillStyle = '#3a3550';
    ctx.fillRect(-6, 20, 44, 1);

    if (state === 'open') {
      const grd = ctx.createLinearGradient(0, 0, 0, 20);
      grd.addColorStop(0, '#030207');
      grd.addColorStop(0.6, '#0a0812');
      grd.addColorStop(1, '#161222');
      ctx.fillStyle = grd;
      ctx.fillRect(0, 0, 32, 20);
      ctx.fillStyle = '#2a2640';
      ctx.fillRect(0, 14, 32, 6);
      ctx.fillStyle = '#4a4564';
      ctx.fillRect(0, 14, 32, 1);
      ctx.fillStyle = 'rgba(255,255,255,0.04)';
      ctx.fillRect(2, 15, 28, 1);
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(0, 0, 2, 20);
      ctx.fillRect(30, 0, 2, 20);
    } else if (state === 'locked') {
      ctx.fillStyle = '#080610';
      ctx.fillRect(0, 0, 32, 20);
      // portcullis
      for (let x = 3; x < 30; x += 6) {
        ctx.fillStyle = '#2a2218';
        ctx.fillRect(x, 1, 3, 17);
        ctx.fillStyle = '#8a7448';
        ctx.fillRect(x + 1, 2, 1, 15);
      }
      for (const y of [5, 11, 17]) {
        ctx.fillStyle = '#3a2e1c';
        ctx.fillRect(2, y, 28, 2);
        ctx.fillStyle = '#9d824d';
        ctx.fillRect(2, y, 28, 1);
      }
      // lock plate
      const hasKey = game.player.keys > 0;
      const pulse = 0.55 + Math.sin(game.time * 3) * 0.2;
      ctx.fillStyle = hasKey ? `rgba(216,180,90,${pulse})` : '#5b4a2a';
      ctx.fillRect(12, 7, 8, 8);
      ctx.fillStyle = '#2a1c08';
      ctx.fillRect(15, 10, 2, 3);
      ctx.beginPath();
      ctx.arc(16, 9, 2, 0, Math.PI * 2);
      ctx.fill();
    } else if (state === 'boss') {
      // ornate double door
      ctx.fillStyle = '#080610';
      ctx.fillRect(0, 0, 32, 20);
      const grd = ctx.createLinearGradient(0, 0, 0, 20);
      grd.addColorStop(0, '#2b2020');
      grd.addColorStop(1, '#1a1218');
      ctx.fillStyle = grd;
      ctx.fillRect(1, 1, 30, 19);
      // panels
      ctx.fillStyle = '#171018';
      ctx.fillRect(3, 3, 11, 15);
      ctx.fillRect(18, 3, 11, 15);
      ctx.strokeStyle = '#9a7938';
      ctx.lineWidth = 1;
      ctx.strokeRect(3, 3, 11, 15);
      ctx.strokeRect(18, 3, 11, 15);
      // center seam + chains
      ctx.fillStyle = '#0c080e';
      ctx.fillRect(15, 0, 2, 20);
      ctx.strokeStyle = '#5e4a2a';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(2, 2);
      ctx.lineTo(13, 11);
      ctx.moveTo(30, 2);
      ctx.lineTo(19, 11);
      ctx.stroke();
      // eye
      const pulse = 0.7 + Math.sin(game.time * 4) * 0.25;
      const glow = ctx.createRadialGradient(16, 10, 0, 16, 10, 11);
      glow.addColorStop(0, `rgba(255,80,70,${0.45 * pulse})`);
      glow.addColorStop(1, 'rgba(255,80,70,0)');
      ctx.fillStyle = glow;
      ctx.fillRect(5, -1, 22, 22);
      ctx.fillStyle = '#e8d8b0';
      ctx.beginPath();
      ctx.ellipse(16, 10, 5, 3, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#c02e34';
      ctx.beginPath();
      ctx.arc(16, 10, 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#160a0c';
      ctx.fillRect(15.2, 8.4, 1.6, 3.2);
      // gold studs
      ctx.fillStyle = COLORS.gold;
      for (const [sx, sy] of [[5, 5], [27, 5], [5, 17], [27, 17]]) ctx.fillRect(sx, sy, 2, 2);
    } else if (state === 'sealed') {
      ctx.fillStyle = '#2a2740';
      ctx.fillRect(0, 0, 32, 20);
      ctx.fillStyle = '#34304d';
      ctx.fillRect(1, 1, 30, 18);
      ctx.fillStyle = 'rgba(10,8,16,0.55)';
      ctx.fillRect(0, 9, 32, 1);
      ctx.fillRect(10, 0, 1, 20);
      ctx.fillRect(21, 0, 1, 20);
      const pulse = 0.5 + Math.sin(game.time * 2.4) * 0.2;
      ctx.strokeStyle = `rgba(200,70,80,${pulse})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(16, 10, 6, 0, Math.PI * 2);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(16, 5);
      ctx.lineTo(19, 10);
      ctx.lineTo(16, 15);
      ctx.lineTo(13, 10);
      ctx.closePath();
      ctx.stroke();
    }
    ctx.restore();
  }

  // -------------------------------------------------------------------------
  // Scene
  // -------------------------------------------------------------------------
  drawScene(ctx, game, snapshot = false) {
    const room = ROOMS[game.roomId];
    const shake = snapshot ? 0 : game.shake;
    ctx.save();
    if (shake > 0.2) ctx.translate(Math.round(rand(-shake, shake)), Math.round(rand(-shake, shake)));

    ctx.drawImage(this.getBackground(game.roomId), 0, 0);

    for (const dir of ['n', 's', 'w', 'e']) {
      const state = game.doorStates[game.roomId]?.[dir];
      if (state) this.drawDoor(ctx, dir, state, game);
    }

    for (let i = 0; i < (room.torches || []).length; i++) {
      const t = room.torches[i];
      const pos = game.torchFlamePos(t);
      const sc = t.dir === 'n' || t.dir === 's' ? 1 : 0.86;
      drawFlame(ctx, pos.x, pos.y, game.time, i * 3.1, sc);
    }

    for (const sign of room.signs || []) {
      drawSign(ctx, { x: c(sign.tx), y: c(sign.ty) });
    }
    for (const pot of game.roomState.pots) drawPot(ctx, pot, game.time);
    for (const chest of game.roomState.chests) drawChest(ctx, chest, game.time);
    for (const p of game.pickups) drawPickup(ctx, p, game.time);

    const entities = [...game.enemies.filter((e) => !e.dead), game.player];
    entities.sort((a, b) => a.y - b.y);
    for (const e of entities) {
      if (e === game.player && game.player.dead) ctx.globalAlpha = 0.55;
      e.draw(ctx, game.time);
      ctx.globalAlpha = 1;
    }

    for (const pr of game.projectiles) drawProjectile(ctx, pr, game.time);
    for (const p of game.particles) drawParticle(ctx, p);

    // warm torch light + boss aura
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < (room.torches || []).length; i++) {
      const t = room.torches[i];
      const pos = game.torchFlamePos(t);
      const flicker = 0.82 + Math.sin(game.time * 9 + i * 2.3) * 0.18;
      const grd = ctx.createRadialGradient(pos.x, pos.y, 0, pos.x, pos.y, 74);
      grd.addColorStop(0, `rgba(255,166,76,${0.12 * flicker})`);
      grd.addColorStop(0.5, `rgba(255,120,48,${0.045 * flicker})`);
      grd.addColorStop(1, 'rgba(255,100,40,0)');
      ctx.fillStyle = grd;
      ctx.fillRect(pos.x - 80, pos.y - 80, 160, 160);
    }
    if (game.boss && !game.boss.dead) {
      const exposed = game.boss.exposed > 0;
      const grd = ctx.createRadialGradient(game.boss.x, game.boss.y, 0, game.boss.x, game.boss.y, 90);
      grd.addColorStop(0, exposed ? 'rgba(255,72,62,0.1)' : 'rgba(140,80,255,0.05)');
      grd.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = grd;
      ctx.fillRect(game.boss.x - 95, game.boss.y - 95, 190, 190);
    }
    ctx.restore();

    ctx.restore();

    if (game.vignette) ctx.drawImage(game.vignette, 0, 0);
    if (game.flashRed > 0) {
      ctx.fillStyle = `rgba(190,24,38,${game.flashRed * 0.55})`;
      ctx.fillRect(0, 0, W, H);
    }
    if (game.flashWhite > 0) {
      ctx.fillStyle = `rgba(255,245,220,${game.flashWhite * 0.45})`;
      ctx.fillRect(0, 0, W, H);
    }
  }
}

import { W, H, COLORS, FONT, clamp } from './config.js';
import { ROOMS, MAP_CELLS } from './world.js';
import {
  drawPixelHeart, drawKeyIcon, drawBossKeyIcon, drawSparkle, drawFlame,
  drawTorchBracket, drawEmber, rect, shadow,
} from './sprites.js';

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

function label(ctx, text, x, y, size = 8, color = COLORS.white, align = 'left', weight = 'bold', spacing = 0) {
  ctx.save();
  ctx.font = `${weight} ${size}px ${FONT}`;
  ctx.textAlign = align;
  ctx.textBaseline = 'top';
  ctx.fillStyle = color;
  ctx.letterSpacing = `${spacing}px`;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function serif(ctx, text, x, y, size, fill, align = 'center', spacing = 0) {
  ctx.save();
  ctx.font = `700 ${size}px Georgia, "DejaVu Serif", "Times New Roman", serif`;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.fillStyle = fill;
  ctx.letterSpacing = `${spacing}px`;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
}

