        g.beginPath();
        g.moveTo(xx, yy - 4);
        g.lineTo(xx + 4, yy);
        g.lineTo(xx, yy + 4);
        g.lineTo(xx - 4, yy);
        g.closePath();
        g.fill();
      }
    }
