5:   ROOMS, MAP_CELLS, buildSolid, doorRect, roomSpawn, neighborId, tileCenter,
6: } from './world.js';
7: import { Player, Enemy, Boss, Projectile, Pickup } from './entities.js';
8: import { WorldView } from './view.js';
9: import {
10:   drawHUD, drawTitle, drawOverlays, makeVignette, buildTitleBackground, makeTitleEmbers,
11: } from './ui.js';
12: 
13: const DIRECTIONS = ['n', 's', 'w', 'e'];
14: 
15: export class Game {
16:   constructor(canvas, ctx, input, audio) {
17:     this.canvas = canvas;
18:     this.ctx = ctx;
19:     this.input = input;
20:     this.audio = audio;
21:     this.time = 0;
22:     this.mode = 'title';
23:     this.shake = 0;
24:     this.hitStop = 0;
25:     this.flashRed = 0;
26:     this.flashWhite = 0;
27:     this.bgCache = new Map();
28:     this.solidCache = new Map();
29:     this.titleTime = 0;
30:     this.titleEmbers = makeTitleEmbers();
31:     this.titleBg = buildTitleBackground();
32:     this.vignette = makeVignette();
33:     this.view = new WorldView();
34: 
35:     this.resetRunState();
36:     this.mode = 'title';
37:   }
38: 
39:   // -------------------------------------------------------------------------
40:   // Run setup
41:   // -------------------------------------------------------------------------
42:   resetRunState() {
43:     this.player = new Player(this, W / 2, H - 70, 'up');
44:     this.roomRuntimes = new Map();
45:     this.doorStates = {};
46:     for (const [id, room] of Object.entries(ROOMS)) {
47:       this.doorStates[id] = { ...room.doors };
48:     }
49:     this.roomId = '1,2';
50:     this.roomState = this.getRuntime('1,2');
51:     this.enemies = [];
52:     this.boss = null;
53:     this.projectiles = [];
54:     this.pickups = [];
55:     this.particles = [];
56:     this.visited = new Set(['1,2']);
57:     this.toast = null;
58:     this.message = null;
59:     this.reward = null;
60:     this.transition = null;
61:     this.roomBanner = null;
62:     this.bossBanner = 0;
63:     this.cinematic = 0;
64:     this.deathTimer = 0;
65:     this.victoryTime = 0;
66:     this.runTime = 0;
67:     this.kills = 0;
68:     this.deaths = 0;
69:     this.hintTimer = 7;
70:     this.doorHintCooldown = 0;
71:     this.ambientTimer = 0;
72:     this.shake = 0;
73:     this.hitStop = 0;
74:     this.flashRed = 0;
75:     this.flashWhite = 0;
76:     this.player.dead = false;
77:   }
78: 
79:   startRun() {
80:     this.resetRunState();
81:     this.mode = 'playing';
82:     this.enterRoom('1,2', null);
83:     this.player.x = W / 2;
84:     this.player.y = H - 70;
85:     this.player.facing = 'up';
86:     this.roomBanner = { name: ROOMS['1,2'].name, timer: 2.8, max: 2.8 };
87:     this.hintTimer = 9;
88:     this.audio.ensure();
89:     this.audio.startMusic('explore');
90:     this.showToast('Find the two small keys. The warden keeps the Boss Key.', 4.2);
91:   }
92: 
93:   debugStart(kind) {
94:     this.startRun();
95:     this.hintTimer = 0;
96:     const open = (id, dir) => {
97:       if (this.doorStates[id]) this.doorStates[id][dir] = 'open';
98:     };
99:     const clear = (...ids) => ids.forEach((id) => { this.getRuntime(id).cleared = true; });
100:     if (kind === 'boss') {
101:       clear('0,0', '0,1', '1,1', '2,1', '2,0');
102:       this.player.keys = 2;
103:       this.player.bossKey = true;
104:       ['0,0', '0,1', '1,1', '2,1', '2,0'].forEach((id) => this.visited.add(id));
105:       open('1,1', 'n');
106:       this.enterRoom('1,0', 's');
107:       this.player.x = W / 2;
108:       this.player.y = H - 66;
109:       this.player.facing = 'up';
110:       this.roomBanner = null;
111:       this.bossBanner = 0;
112:       this.cinematic = 0;
113:       if (this.boss) {
114:         this.boss.state = 'hover';
115:         this.boss.intro = false;
116:         this.boss.stateTimer = 0.7;
117:         this.boss.x = W / 2;
118:         this.boss.y = 92;
119:       }
120:       this.showToast('DEBUG: Boss arena', 1.5);
121:     } else if (kind === 'vault') {
122:       clear('0,1', '1,1', '2,1');
123:       this.player.keys = 2;
124:       ['0,1', '1,1', '2,1'].forEach((id) => this.visited.add(id));
125:       open('0,1', 'n');
126:       this.enterRoom('0,0', 's');
127:       this.player.x = W / 2;
128:       this.player.y = H - 66;
129:       this.player.facing = 'up';
130:       this.roomBanner = null;
131:       this.showToast('DEBUG: Warden arena', 1.5);
132:     } else if (kind === 'hub') {
133:       clear('0,1', '2,1');
134:       this.player.keys = 2;
135:       this.enterRoom('1,1', 's');
136:       this.player.x = W / 2;
137:       this.player.y = H - 70;
138:       this.roomBanner = null;
139:       this.showToast('DEBUG: Grand Hall', 1.5);
140:     } else if (kind === 'map') {
141:       this.player.keys = 2;
142:       this.player.bossKey = true;
143:       this.player.maxHp = 6;
144:       this.player.hp = 6;
145:       Object.keys(ROOMS).forEach((id) => this.visited.add(id));
146:       this.showToast('DEBUG: All doors visible', 1.5);
147:     }
148:   }
149: 
150:   getRuntime(id) {
151:     if (!this.roomRuntimes.has(id)) {
152:       const def = ROOMS[id];
153:       const pots = (def.props || [])
154:         .filter((p) => p.type === 'pot')
155:         .map((p) => ({ x: tileCenter(p.tx), y: tileCenter(p.ty), broken: false }));
156:       const chests = (def.chests || []).map((ch) => ({
157:         ...ch,
158:         x: tileCenter(ch.tx),
159:         y: tileCenter(ch.ty),
160:         opened: false,
161:         hidden: !!ch.hidden,
162:       }));
163:       this.roomRuntimes.set(id, { pots, chests, cleared: false });
164:     }
165:     return this.roomRuntimes.get(id);
166:   }
167: 
168:   getSolid(id) {
169:     if (!this.solidCache.has(id)) this.solidCache.set(id, buildSolid(ROOMS[id]));
170:     return this.solidCache.get(id);
171:   }
172: 
173:   enterRoom(id, fromDir) {
174:     const def = ROOMS[id];
175:     if (!def) return;
176:     this.roomId = id;
177:     this.visited.add(id);
178:     this.roomState = this.getRuntime(id);
179:     this.enemies = [];
180:     this.boss = null;
181:     this.projectiles = [];
182:     this.pickups = [];
183: 
184:     if (!this.roomState.cleared) {
185:       for (const e of def.enemies || []) {
186:         this.enemies.push(new Enemy(this, e.type, tileCenter(e.tx), tileCenter(e.ty)));
187:       }
188:     }
189: 
190:     const spawn = roomSpawn(id, fromDir);
191:     this.player.x = spawn.x;
192:     this.player.y = spawn.y;
193:     this.player.facing = spawn.facing;
194:     this.player.kbx = 0;
195:     this.player.kby = 0;
196: 
197:     if (def.boss && !this.roomState.cleared) {
198:       this.boss = new Boss(this, W / 2, 100);
199:       this.enemies.push(this.boss);
200:       this.bossBanner = 3.2;
201:       this.cinematic = 2.3;
202:       if (this.doorStates[id]) this.doorStates[id].s = 'sealed';
203:       if (this.doorStates['1,1']) this.doorStates['1,1'].n = 'sealed';
204:       this.audio.setMusic('boss');
205:     } else {
206:       this.audio.setMusic('explore');
207:     }
208: 
209:     this.roomBanner = { name: def.name, timer: 2.7, max: 2.7 };
210:   }
211: 
212:   // -------------------------------------------------------------------------
213:   // Update
214:   // -------------------------------------------------------------------------
215:   update(dt) {
216:     this.time += dt;
217:     this.shake = Math.max(0, this.shake - dt * 28);
218:     this.flashRed = Math.max(0, this.flashRed - dt * 3.2);
219:     this.flashWhite = Math.max(0, this.flashWhite - dt * 1.7);
220: 
221:     if (this.input.justPressed('mute')) {
222:       const muted = this.audio.toggleMute();
223:       if (this.mode === 'playing' || this.mode === 'paused') {
224:         this.showToast(muted ? 'Sound off.' : 'Sound on.', 1.2);
225:       }
226:     }
227: 
228:     if (this.mode === 'title') {
229:       this.updateTitle(dt);
230:       return;
231:     }
232:     if (this.mode === 'playing') {
233:       if (this.input.justPressed('pause')) {
234:         this.togglePause();
235:         return;
236:       }
237:       this.updatePlaying(dt);
238:       return;
239:     }
240:     if (this.mode === 'paused') {
241:       if (this.input.justPressed('pause') || this.input.justPressed('confirm')) this.togglePause();
242:       return;
243:     }
244:     if (this.mode === 'reward') {
245:       this.updateReward(dt);
246:       return;
247:     }
248:     if (this.mode === 'message') {
249:       this.updateMessage(dt);
250:       return;
251:     }
252:     if (this.mode === 'dead') {
253:       this.updateDead(dt);
254:       return;
255:     }
256:     if (this.mode === 'victory') {
257:       this.updateVictory(dt);
258:     }
259:   }
260: 
261:   updateTitle(dt) {
262:     this.titleTime += dt;
263:     for (const e of this.titleEmbers) {
264:       e.y -= e.vy * dt;
265:       e.x += Math.sin(this.titleTime * 0.8 + e.phase) * 5 * dt;
266:       e.life -= dt;
267:       if (e.life <= 0) {
268:         e.x = rand(30, W - 30);
269:         e.y = rand(H * 0.5, H + 20);
270:         e.vy = rand(9, 26);
271:         e.life = rand(2.5, 7);
272:         e.size = rand(0.7, 2);
273:       }
274:     }
275:     if (
276:       this.input.justPressed('confirm') ||
277:       this.input.justPressed('attack') ||
278:       this.input.justPressed('interact')
279:     ) {
280:       this.startRun();
281:     }
282:   }
283: 
284:   updatePlaying(dt) {
285:     this.runTime += dt;
286:     this.updateTimers(dt);
287: 
288:     if (this.transition) {
289:       this.transition.t += dt;
290:       this.updateParticles(dt);
291:       if (this.transition.t >= this.transition.dur) this.transition = null;
292:       return;
293:     }
294: 
295:     if (this.cinematic > 0) {
296:       this.cinematic -= dt;
297:       this.updateAmbient(dt);
298:       this.updateParticles(dt);
299:       if (this.boss && !this.boss.dead) this.boss.update(dt);
300:       return;
301:     }
302: 
303:     if (this.hitStop > 0) {
304:       this.hitStop -= dt;
305:       return;
306:     }
307: 
308:     if (this.player.dead) return;
309: 
310:     this.player.update(dt);
311:     for (const e of this.enemies) {
312:       if (!e.dead) e.update(dt);
313:     }
314:     this.enemies = this.enemies.filter((e) => !e.dead);
315:     if (this.mode !== 'playing') return;
316: 
317:     this.updateProjectiles(dt);
318:     if (this.mode !== 'playing') return;
319:     this.updatePickups(dt);
320:     this.updateParticles(dt);
321:     this.updateAmbient(dt);
322: 
323:     this.checkDoors();
324:     if (this.transition) return;
325:     this.checkRoomClear();
326:   }
327: 
328:   updateTimers(dt) {
329:     if (this.toast) {
330:       this.toast.timer -= dt;
331:       if (this.toast.timer <= 0) this.toast = null;
332:     }
333:     if (this.roomBanner) {
334:       this.roomBanner.timer -= dt;
335:       if (this.roomBanner.timer <= 0) this.roomBanner = null;
336:     }
337:     if (this.bossBanner > 0) this.bossBanner -= dt;
338:     if (this.hintTimer > 0) this.hintTimer -= dt;
339:     this.doorHintCooldown = Math.max(0, this.doorHintCooldown - dt);
340:   }
341: 
342:   updateProjectiles(dt) {
343:     for (const pr of this.projectiles) {
344:       if (!pr.dead) pr.update(dt);
345:       if (this.mode !== 'playing') return;
346:     }
347:     this.projectiles = this.projectiles.filter((p) => !p.dead);
348:   }
349: 
350:   updatePickups(dt) {
351:     for (const p of this.pickups) p.update(dt);
352:     this.pickups = this.pickups.filter((p) => !p.dead);
353:   }
354: 
355:   updateParticles(dt) {
356:     for (const p of this.particles) {
357:       p.life -= dt;
358:       p.x += p.vx * dt;
359:       p.y += p.vy * dt;
360:       p.vy += (p.gravity || 0) * dt;
361:       p.vx *= Math.pow(p.drag ?? 0.12, dt);
362:       p.vy *= Math.pow(p.drag ?? 0.12, dt);
363:       p.rot = (p.rot || 0) + (p.spin || 0) * dt;
364:     }
365:     this.particles = this.particles.filter((p) => p.life > 0);
366:   }
367: 
368:   updateAmbient(dt) {
369:     this.ambientTimer -= dt;
370:     if (this.ambientTimer > 0) return;
371:     this.ambientTimer = rand(0.1, 0.26);
372:     const room = ROOMS[this.roomId];
373:     if (!room) return;
374:     const sources = (room.torches || []).map((t) => this.torchFlamePos(t));
375:     for (const p of room.props || []) {
376:       if (p.type === 'brazier') sources.push({ x: p.tx * 16 + 8, y: p.ty * 16 + 2 });
377:     }
378:     if (!sources.length) return;
379:     const pos = sources[Math.floor(rand(0, sources.length))];
380:     this.addParticle({
381:       kind: 'spark',
382:       x: pos.x + rand(-4, 4),
383:       y: pos.y + rand(-2, 2),
384:       vx: rand(-5, 5),
385:       vy: rand(-30, -14),
386:       gravity: -3,
387:       drag: 0.7,
388:       life: rand(0.7, 1.6),
389:       maxLife: 1.6,
390:       size: rand(0.8, 1.8),
391:       color: Math.random() < 0.4 ? '#ffd27a' : '#ff9a4a',
392:       alpha: 0.85,
393:     });
394:   }
395: 
396:   torchFlamePos(t) {
397:     if (t.dir === 'n') return { x: t.tx * 16 + 8, y: 14 };
398:     if (t.dir === 's') return { x: t.tx * 16 + 8, y: H - 18 };
399:     if (t.dir === 'w') return { x: 19, y: t.ty * 16 + 8 };
400:     return { x: W - 19, y: t.ty * 16 + 8 };
401:   }
402: 
403:   togglePause() {
404:     if (this.mode === 'playing') {
405:       this.mode = 'paused';
406:       this.audio.sfx('pause');
407:     } else if (this.mode === 'paused') {
408:       this.mode = 'playing';
409:       this.audio.sfx('pause');
410:     }
411:   }
412: 
413:   // -------------------------------------------------------------------------
414:   // Doors, transitions, keys
415:   // -------------------------------------------------------------------------
416:   nearDoor(dir) {
417:     const p = this.player;
418:     if (dir === 'n') return Math.abs(p.x - W / 2) < 22 && p.y < 40;
419:     if (dir === 's') return Math.abs(p.x - W / 2) < 22 && p.y > H - 40;
420:     if (dir === 'w') return Math.abs(p.y - H / 2) < 24 && p.x < 40;
421:     return Math.abs(p.y - H / 2) < 24 && p.x > W - 40;
422:   }
423: 
424:   pastThreshold(dir) {
425:     const p = this.player;
426:     if (dir === 'n') return p.y < 10;
427:     if (dir === 's') return p.y > H - 10;
428:     if (dir === 'w') return p.x < 10;
429:     return p.x > W - 10;
430:   }
431: 
432:   checkDoors() {
433:     for (const dir of DIRECTIONS) {
434:       const state = this.doorStates[this.roomId]?.[dir];
435:       if (!state) continue;
436:       if (this.nearDoor(dir)) {
437:         if (state === 'locked') {
438:           if (this.doorHintCooldown > 0) return;
439:           if (this.player.keys > 0) {
440:             this.unlockDoor(dir, false);
441:           } else {
442:             this.showToast('Locked tight. A small key is needed.', 2.3);
443:             this.doorHintCooldown = 2.3;
444:           }
445:           return;
446:         }
447:         if (state === 'boss') {
448:           if (this.doorHintCooldown > 0) return;
449:           if (this.player.bossKey) {
450:             this.unlockDoor(dir, true);
451:           } else {
452:             this.showToast('The great door is bound to a Boss Key.', 2.7);
453:             this.doorHintCooldown = 2.7;
454:           }
455:           return;
456:         }
457:         if (state === 'sealed') {
458:           if (this.doorHintCooldown <= 0) {
459:             this.showToast(
460:               ROOMS[this.roomId].boss ? 'Sealed until the Hollow Eye falls.' : 'Sealed from the other side.',
461:               2.4
462:             );
463:             this.doorHintCooldown = 2.4;
464:           }
465:           return;
466:         }
467:       }
468:       if (state === 'open' && this.pastThreshold(dir)) {
469:         this.startTransition(dir);
470:         return;
471:       }
472:     }
473:   }
474: 
475:   unlockDoor(dir, isBoss) {
476:     const nd = neighborId(this.roomId, dir);
477:     if (isBoss) {
478:       this.player.bossKey = false;
479:       this.audio.sfx('bossDoor');
480:       this.shake = Math.max(this.shake, 9);
481:       this.flashWhite = 0.25;
482:       this.showToast('The Boss Key turns. The great door opens.', 3);
483:       this.cinematic = Math.max(this.cinematic, 0.55);
484:     } else {
485:       this.player.keys--;
486:       this.audio.sfx('unlock');
487:       this.showToast('The lock clicks open.', 1.8);
488:       this.shake = Math.max(this.shake, 2.5);
489:     }
490:     if (this.doorStates[this.roomId]) this.doorStates[this.roomId][dir] = 'open';
491:     if (nd && this.doorStates[nd]) this.doorStates[nd][OPPOSITE[dir]] = 'open';
492:     const c = DOOR_CENTER[dir];
493:     this.spark(c.x, c.y, 10, '#ffd27a');
494:     this.doorHintCooldown = 1.2;
495:   }
496: 
497:   startTransition(dir) {
498:     const target = neighborId(this.roomId, dir);
499:     if (!target || !ROOMS[target]) {
500:       this.showToast('A dead end.', 1.2);
501:       return;
502:     }
503:     const snap = document.createElement('canvas');
504:     snap.width = W;
505:     snap.height = H;
506:     const sctx = snap.getContext('2d');
507:     const oldShake = this.shake;
508:     this.shake = 0;
509:     this.view.drawScene(sctx, this, true);
510:     this.shake = oldShake;
511:     this.transition = { dir, t: 0, dur: 0.32, snap };
512:     this.enterRoom(target, dir);
513:   }
514: 
515:   // -------------------------------------------------------------------------
516:   // Interaction and items
517:   // -------------------------------------------------------------------------
518:   tryInteract(player) {
519:     const def = ROOMS[this.roomId];
520:     for (const sign of def.signs || []) {
521:       const x = tileCenter(sign.tx);
522:       const y = tileCenter(sign.ty);
523:       if (dist(player.x, player.y, x, y) < 31) {
524:         this.showMessage(sign.text);
525:         return;
526:       }
527:     }
528:     for (const chest of this.roomState.chests) {
529:       if (chest.hidden) continue;
530:       if (dist(player.x, player.y, chest.x, chest.y) < 31) {
531:         if (chest.opened) this.showToast('Empty.', 1.0);
532:         else this.openChest(chest);
533:         return;
534:       }
535:     }
536:   }
537: 
538:   openChest(chest) {
539:     if (chest.opened || chest.hidden) return;
540:     chest.opened = true;
541:     this.audio.sfx('chest');
542:     this.burst(chest.x, chest.y - 6, 14, '#ffd27a');
543:     let reward = null;
544:     if (chest.content === 'key') {
545:       this.player.keys++;
546:       reward = {
547:         kind: 'key',
548:         title: 'SMALL KEY',
549:         subtitle: this.player.keys > 1 ? 'Two locks now answer to you.' : 'One lock now answers to you.',
550:       };
551:     } else if (chest.content === 'bossKey') {
552:       this.player.bossKey = true;
553:       reward = {
554:         kind: 'bossKey',
555:         title: 'BOSS KEY',
556:         subtitle: 'The great door in the Grand Hall will yield.',
557:       };
558:       this.shake = Math.max(this.shake, 6);
559:     } else if (chest.content === 'heartContainer') {
560:       this.player.maxHp++;
561:       this.player.hp = this.player.maxHp;
562:       reward = {
563:         kind: 'heartContainer',
564:         title: 'HEART CONTAINER',
565:         subtitle: 'Your life force grows.',
566:       };
567:       this.audio.sfx('heart');
568:     }
569:     if (reward) {
570:       this.reward = { ...reward, timer: 2.8 };
571:       this.mode = 'reward';
572:       this.flashWhite = 0.22;
573:     }
574:   }
575: 
576:   revealChest(id) {
577:     for (const runtime of this.roomRuntimes.values()) {
578:       for (const chest of runtime.chests) {
579:         if (chest.id === id && chest.hidden) {
580:           chest.hidden = false;
581:           if (this.roomState === runtime) {
582:             this.burst(chest.x, chest.y, 22, '#ffd27a');
583:             this.spark(chest.x, chest.y, 14, '#fff3c4');
584:           }
585:           this.showToast('The Warden falls. A Boss Key chest appears.', 3.2);
586:           this.audio.sfx('secret');
587:           this.shake = Math.max(this.shake, 5);
588:         }
589:       }
590:     }
591:   }
592: 
593:   showMessage(lines) {
594:     this.message = { lines, shown: 0 };
595:     this.mode = 'message';
596:     this.audio.sfx('pickup');
597:   }
598: 
599:   updateMessage(dt) {
600:     const total = this.message.lines.join('').length;
