59:       if (dir === 'w') { doorTiles.add('0,8'); doorTiles.add('0,9'); }
60:       if (dir === 'e') { doorTiles.add('31,8'); doorTiles.add('31,9'); }
61:     }
62:     for (let x = 0; x < 32; x++) {
63:       for (const y of [0, 17]) {
64:         if (!doorTiles.has(`${x},${y}`)) this.drawWallTile(g, x * TILE, y * TILE, x, y, y === 0 ? 'n' : 's');
65:       }
66:     }
67:     for (let y = 1; y < 17; y++) {
68:       if (!doorTiles.has(`0,${y}`)) this.drawWallTile(g, 0, y * TILE, 0, y, 'w');
69:       if (!doorTiles.has(`31,${y}`)) this.drawWallTile(g, 31 * TILE, y * TILE, 31, y, 'e');
70:     }
71: 
72:     // inner shadow around the room
73:     let grad = g.createLinearGradient(0, TILE, 0, TILE + 34);
74:     grad.addColorStop(0, 'rgba(3,2,7,0.62)');
75:     grad.addColorStop(1, 'rgba(3,2,7,0)');
76:     g.fillStyle = grad;
77:     g.fillRect(TILE, TILE, W - TILE * 2, 34);
78:     grad = g.createLinearGradient(0, H - TILE, 0, H - TILE - 30);
79:     grad.addColorStop(0, 'rgba(3,2,7,0.55)');
80:     grad.addColorStop(1, 'rgba(3,2,7,0)');
81:     g.fillStyle = grad;
82:     g.fillRect(TILE, H - TILE - 30, W - TILE * 2, 30);
83:     grad = g.createLinearGradient(TILE, 0, TILE + 30, 0);
84:     grad.addColorStop(0, 'rgba(3,2,7,0.5)');
85:     grad.addColorStop(1, 'rgba(3,2,7,0)');
86:     g.fillStyle = grad;
87:     g.fillRect(TILE, TILE, 30, H - TILE * 2);
88:     grad = g.createLinearGradient(W - TILE, 0, W - TILE - 30, 0);
89:     grad.addColorStop(0, 'rgba(3,2,7,0.5)');
90:     grad.addColorStop(1, 'rgba(3,2,7,0)');
91:     g.fillStyle = grad;
92:     g.fillRect(W - TILE - 30, TILE, 30, H - TILE * 2);
93: 
94:     for (const b of room.banners || []) this.drawBanner(g, b);
95:     if (room.boss) this.drawChains(g);
96:     for (const p of room.props || []) {
97:       if (p.type === 'pillar') this.drawPillar(g, p);
98:       else if (p.type === 'statue') this.drawStatue(g, p);
99:       else if (p.type === 'brazier') this.drawBrazier(g, p);
100:       else if (p.type === 'rubble') this.drawRubble(g, p);
101:       else if (p.type === 'bones') this.drawBones(g, p);
102:     }
103: 
104:     for (const t of room.torches || []) this.drawTorchBracketFor(g, t);
105: 
106:     // faint wall grime
107:     g.globalAlpha = 0.1;
108:     g.fillStyle = '#000';
109:     for (let i = 0; i < 20; i++) {
110:       const x = hash(i, 3) * W;
111:       const y = hash(i, 7) * H;
112:       g.fillRect(x, y, 1, 1);
113:     }
114:     g.globalAlpha = 1;
115: 
116:     this.bgCache.set(roomId, cv);
117:     return cv;
118:   }
