120:   drawFloorTile(g, px, py, x, y) {
121:     const n = hash(x, y);
122:     const base = n > 0.66 ? '#201e2f' : n > 0.3 ? '#1c1a29' : '#191725';
123:     g.fillStyle = base;
124:     g.fillRect(px, py, TILE, TILE);
125:     // bevel
126:     g.fillStyle = 'rgba(255,255,255,0.035)';
127:     g.fillRect(px, py, TILE, 1);
128:     g.fillRect(px, py, 1, TILE);
129:     g.fillStyle = 'rgba(0,0,0,0.24)';
130:     g.fillRect(px, py + TILE - 1, TILE, 1);
131:     g.fillRect(px + TILE - 1, py, 1, TILE);
132:     // seams
133:     g.fillStyle = 'rgba(6,5,10,0.45)';
134:     g.fillRect(px, py + 8, TILE, 1);
135:     g.fillRect(px + 8, py, 1, TILE);
136:     if (n > 0.88) {
137:       g.strokeStyle = 'rgba(0,0,0,0.4)';
138:       g.lineWidth = 1;
139:       g.beginPath();
140:       g.moveTo(px + 4, py + 3);
141:       g.lineTo(px + 8, py + 7);
142:       g.lineTo(px + 6, py + 12);
143:       g.stroke();
144:     }
145:     if (n < 0.035) {
146:       g.fillStyle = 'rgba(70,105,66,0.22)';
147:       g.beginPath();
148:       g.arc(px + 5, py + 11, 2.2, 0, Math.PI * 2);
149:       g.arc(px + 9, py + 9, 1.4, 0, Math.PI * 2);
150:       g.fill();
151:     }
152:   }
