154:   drawWallTile(g, px, py, x, y, side) {
155:     const n = hash(x * 2 + 11, y * 3 + 7);
156:     g.fillStyle = '#2b2840';
157:     g.fillRect(px, py, TILE, TILE);
158:     g.fillStyle = n > 0.5 ? '#322e4a' : '#2e2a45';
159:     g.fillRect(px + 1, py + 2, TILE - 2, TILE - 4);
160:     // top face
161:     g.fillStyle = '#484463';
162:     g.fillRect(px, py, TILE, 2);
163:     g.fillStyle = '#3c3856';
164:     g.fillRect(px, py + 2, TILE, 2);
165:     // bottom shadow
166:     g.fillStyle = '#171522';
167:     g.fillRect(px, py + TILE - 3, TILE, 3);
168:     // brick seams
169:     g.fillStyle = 'rgba(8,7,14,0.55)';
170:     g.fillRect(px, py + 8, TILE, 1);
171:     const seamX = y % 2 === 0 ? px + 5 : px + 11;
172:     g.fillRect(seamX, py + 2, 1, 6);
173:     g.fillRect(y % 2 === 0 ? px + 12 : px + 3, py + 9, 1, 5);
174:     // highlights
175:     g.fillStyle = 'rgba(255,255,255,0.05)';
176:     g.fillRect(px + 1, py + 3, TILE - 2, 1);
177:     if (n > 0.82) {
178:       g.strokeStyle = 'rgba(10,8,16,0.65)';
179:       g.lineWidth = 1;
180:       g.beginPath();
181:       g.moveTo(px + 3, py + 4);
182:       g.lineTo(px + 6, py + 7);
183:       g.lineTo(px + 5, py + 12);
184:       g.stroke();
185:     }
186:     if (n < 0.07) {
187:       g.fillStyle = 'rgba(72,104,66,0.32)';
188:       g.fillRect(px + 2, py + 11, 3, 2);
189:       g.fillRect(px + 4, py + 9, 2, 3);
190:     }
191:     if (side === 'n' && y === 0) {
192:       g.fillStyle = 'rgba(4,3,8,0.9)';
193:       g.fillRect(px, py, TILE, 1);
194:     }
195:   }
