197:   drawCarpet(g, kind) {
198:     const left = W / 2 - 24;
199:     const right = W / 2 + 24;
200:     const drawStrip = (x, y, w, h) => {
201:       g.fillStyle = '#4d1923';
202:       g.fillRect(x, y, w, h);
203:       g.fillStyle = '#5c202b';
204:       g.fillRect(x + 3, y + 3, w - 6, h - 6);
205:       g.strokeStyle = 'rgba(200,164,74,0.45)';
206:       g.lineWidth = 2;
207:       g.strokeRect(x + 1, y + 1, w - 2, h - 2);
208:       g.strokeStyle = 'rgba(30,10,14,0.6)';
209:       g.lineWidth = 1;
210:       g.strokeRect(x + 5, y + 5, w - 10, h - 10);
211:       // diamond pattern
212:       g.fillStyle = 'rgba(216,180,90,0.1)';
213:       for (let yy = y + 12; yy < y + h - 8; yy += 22) {
214:         for (let xx = x + 12; xx < x + w - 8; xx += 22) {
215:           g.beginPath();
216:           g.moveTo(xx, yy - 4);
217:           g.lineTo(xx + 4, yy);
218:           g.lineTo(xx, yy + 4);
219:           g.lineTo(xx - 4, yy);
220:           g.closePath();
221:           g.fill();
222:         }
223:       }
224:     };
225:     if (kind === 'vertical') drawStrip(left, TILE, right - left, H - TILE * 2);
226:     if (kind === 'cross') {
227:       drawStrip(left, TILE, right - left, H - TILE * 2);
228:       drawStrip(TILE, H / 2 - 24, W - TILE * 2, 48);
229:     }
230:   }
