232:   drawMosaic(g, mosaic, boss) {
233:     const x = c(mosaic.tx);
234:     const y = c(mosaic.ty);
235:     const r = mosaic.r;
236:     g.save();
237:     g.translate(x, y);
238:     g.globalAlpha = 0.62;
239:     g.strokeStyle = boss ? 'rgba(190,72,86,0.55)' : 'rgba(94,178,170,0.4)';
240:     g.lineWidth = 2;
241:     g.beginPath();
242:     g.arc(0, 0, r, 0, Math.PI * 2);
243:     g.stroke();
244:     g.lineWidth = 1;
245:     g.strokeStyle = 'rgba(216,180,90,0.34)';
246:     g.beginPath();
247:     g.arc(0, 0, r - 7, 0, Math.PI * 2);
248:     g.stroke();
249:     g.beginPath();
250:     g.arc(0, 0, r - 18, 0, Math.PI * 2);
251:     g.stroke();
252:     // rune marks
253:     for (let i = 0; i < 8; i++) {
254:       const a = (i / 8) * Math.PI * 2;
255:       g.save();
256:       g.rotate(a);
257:       g.fillStyle = boss ? 'rgba(200,78,88,0.4)' : 'rgba(216,180,90,0.32)';
258:       g.beginPath();
259:       g.moveTo(r - 14, -3);
260:       g.lineTo(r - 8, 0);
261:       g.lineTo(r - 14, 3);
262:       g.closePath();
263:       g.fill();
264:       g.restore();
265:     }
266:     // central motif
267:     g.strokeStyle = boss ? 'rgba(210,88,92,0.62)' : 'rgba(79,185,176,0.5)';
268:     g.lineWidth = 2;
269:     if (boss) {
270:       g.beginPath();
271:       g.ellipse(0, 0, 20, 11, 0, 0, Math.PI * 2);
272:       g.stroke();
273:       g.fillStyle = 'rgba(210,88,92,0.55)';
274:       g.beginPath();
275:       g.ellipse(0, 0, 7, 9, 0, 0, Math.PI * 2);
276:       g.fill();
277:       g.fillStyle = 'rgba(10,6,12,0.9)';
278:       g.fillRect(-1.5, -8, 3, 16);
279:     } else {
280:       for (let i = 0; i < 3; i++) {
281:         const a = -Math.PI / 2 + (i / 3) * Math.PI * 2;
282:         g.beginPath();
283:         g.moveTo(Math.cos(a) * 17, Math.sin(a) * 17);
284:         g.lineTo(Math.cos(a + 2.2) * 17, Math.sin(a + 2.2) * 17);
285:         g.lineTo(Math.cos(a + 1.1) * 8, Math.sin(a + 1.1) * 8);
286:         g.closePath();
287:         g.stroke();
288:       }
289:     }
290:     g.restore();
291:     g.globalAlpha = 1;
292:   }
