504:   drawDoor(ctx, dir, state, game) {
505:     ctx.save();
506:     if (dir === 'n') ctx.translate(240, 0);
507:     else if (dir === 's') { ctx.translate(272, H); ctx.rotate(Math.PI); }
508:     else if (dir === 'w') { ctx.translate(0, 160); ctx.rotate(-Math.PI / 2); }
509:     else { ctx.translate(W, 128); ctx.rotate(Math.PI / 2); }
510: 
511:     // stone jambs
512:     ctx.fillStyle = '#171522';
513:     ctx.fillRect(-6, 0, 6, 24);
514:     ctx.fillRect(32, 0, 6, 24);
515:     ctx.fillStyle = '#474263';
516:     ctx.fillRect(-5, 0, 4, 22);
517:     ctx.fillRect(32, 0, 4, 22);
518:     ctx.fillStyle = '#625c85';
519:     ctx.fillRect(-5, 0, 1, 22);
520:     ctx.fillRect(32, 0, 1, 22);
521:     ctx.fillStyle = '#211e30';
522:     ctx.fillRect(-6, 20, 44, 4);
523:     ctx.fillStyle = '#3a3550';
524:     ctx.fillRect(-6, 20, 44, 1);
